<?php
class Model { protected $table; public function set_table($t) { $this->table = $t; return $this; } public function all($sql = null, $params = []) { if ($sql) { $st = db()->prepare($sql); $st->execute($params); return $st->fetchAll(); } return db()->query('SELECT * FROM ' . $this->table . ' ORDER BY id DESC LIMIT 500')->fetchAll(); } public function find($id) { $st = db()->prepare('SELECT * FROM ' . $this->table . ' WHERE id = ?'); $st->execute([(int)$id]); return $st->fetch(); } public function insert(array $data) { $cols = array_keys($data); $sql = 'INSERT INTO ' . $this->table . ' (' . implode(',', $cols) . ') VALUES (:' . implode(',:', $cols) . ')'; db()->prepare($sql)->execute($data); return (int)db()->lastInsertId(); } public function update($id, array $data) { $sets = []; foreach ($data as $k => $v) $sets[] = "$k = :$k"; $data['id'] = (int)$id; db()->prepare('UPDATE ' . $this->table . ' SET ' . implode(', ', $sets) . ' WHERE id = :id')->execute($data); } public function delete($id) { db()->prepare('DELETE FROM ' . $this->table . ' WHERE id = ?')->execute([(int)$id]); } public function count() { return (int)db()->query('SELECT COUNT(*) c FROM ' . $this->table)->fetch()['c']; } }
